dslRule:
"Warn about usage of deprecated Platform.ARCH_X86 constant":
org.eclipse.core.runtime.Platform.ARCH_X86
;;

beforeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86;
        System.out.println("Running on " + currentArch);
    }
}

afterExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86; // This line would display a warning.
        System.out.println("Running on " + currentArch);
    }
}

negativeExample:
package test;

import org.eclipse.core.runtime.Platform;

public class Example {
    public void checkArchitecture() {
        String currentArch = Platform.ARCH_X86_64;
        System.out.println("Running on " + currentArch);
    }
}

dslRule:
/*!
@id: eclipse.api.mark_deprecated_for_removal
@description: Add forRemoval=true and specific since attribute to existing @Deprecated annotations (Java 9+).
@severity: WARNING
*/
@java.lang.Deprecated :: sourceVersionGE(9)
=> @java.lang.Deprecated(forRemoval = true, since = "2025-06 (removal in 2027-06 or later)")
;;

beforeExample:
package com.example;

import java.net.URL;
import java.util.Map;

// Minimal dummy interfaces/classes for compilation
interface IPath {}
class FileLocator { static URL find(Object b, IPath p, Map m) { return null; } }
class Bundle {}
class CoreException extends Exception {}

public class MyPlugin {
    @Deprecated
    public URL findResource(IPath path) {
        return FileLocator.find(new Bundle(), path, null);
    }

    @Deprecated
    public void initializeDefaults() throws CoreException {
        // ...
    }

    // This method already has the desired attributes, should not be changed.
    @Deprecated(forRemoval = true, since = "2025-06 (removal in 2027-06 or later)")
    public void alreadyMarkedMethod() {}

    // This method has a different @Deprecated attribute, will be overwritten.
    @Deprecated(forRemoval = false)
    public void specificDeprecatedMethod() {}
}

