negativeExample:
package com.example;

public class AnotherClass {
    // This method is not @Deprecated, so it should not be affected.
    public void normalMethod() {
        System.out.println("This method is fine.");
    }

    // This method uses a different annotation, so it should not be affected.
    @Override
    public String toString() {
        return "AnotherClass instance";
    }

    // If the project source version is below 9, this @Deprecated should not be affected by the rule.
    // (This is implicitly handled by the sourceVersionGE(9) guard during analysis).
    @Deprecated
    public void legacyMethodInOldProject() {}
}
